SELECT NVL(MAX(MENU_NO), #{upperMenuNo}) + 10000
  FROM COMTNMENUINFO
 WHERE UPPER_MENU_NO = #{upperMenuNo}

SELECT NVL(MAX(MENU_ORDR), 0) + 1
  FROM COMTNMENUINFO
 WHERE UPPER_MENU_NO = #{upperMenuNo}

