UPDATE COMTNPROGRMLIST
   SET PROGRM_KOREAN_NM = #{menuNm},
       URL = #{url}
 WHERE PROGRM_FILE_NM = #{progrmFileNm}

UPDATE COMTNMENUINFO
   SET MENU_NM = #{menuNm},
       MENU_ORDR = #{menuOrdr},
       MENU_DC = #{menuNm}
 WHERE MENU_NO = #{menuNo}
